import * as M from './methods-core.js';
import * as C from './core.js';
import {earRef,outputRef} from './methods-data.js';
import {LIBRARY} from './library-data.js';
import {createSpeech} from './speech.js';
import {voiceSelect} from './voice-client.js';
import {getVoice,listeningPath} from './voice-config.js';

export function createMethods({esc,head,button,getState,commit,render,go,toast,stopAudio,retryMistake,openWords,openDictation}){
 let mode='home',lesson='l01',index=0,outputId='o01',reasonId=null,feedback=null,draft='',showHint=false,loop=false,heardIndex=null,raf=0,sessionDate=C.today();
 const speech=createSpeech({toast});
 const stopLoop=()=>{cancelAnimationFrame(raf);raf=0;};
 const leave=()=>{stopLoop();speech.stop();heardIndex=null;};
 function home(){
  const s=getState(),date=C.today(),done=s.methods?.days[date]||{listening:[],output:[]},due=M.reasonQueue(s,date),untagged=s.mistakes.filter(m=>!m.resolved&&!s.methods?.reasons[m.id]);
  return head('ONE GENTLE ROUTINE','今天，知道该怎么学','约 25 分钟，可以拆开做。先回忆，再听懂，最后自己写出来。')+`<section class="panel glass method-routine"><div class="method-steps"><div><span>01 · 约 5 分钟</span><h2>先唤醒旧词</h2><p>${C.dueIds(s).length} 个词已到复习时间。</p>${button('打开词汇复习','method-words')}</div><div><span>02 · 约 5 分钟</span><h2>听出来，拼出来</h2><p>沿用专项听写，声音和拼写分别记录。</p>${button('练五个听写','method-dictation')}</div><div><span>03 · 约 10 分钟</span><h2>吃透一小段听力</h2><p>先听大意 → 对照文本 → 隐藏文本跟读。</p><p class="caption">今天完成 ${done.listening.length} 篇三步精听</p>${button('开始逐句精听','method-listen','data-lesson="l01"')}</div><div><span>04 · 约 5 分钟</span><h2>把提示，慢慢拿开</h2><p>看例句 → 补缺词 → 只看中文写英文。</p><p class="caption">今天完成 ${done.output.length} 句（含自行核对）</p>${button('开始中译英小阶梯','method-output')}</div></div><p class="caption">时间只是建议。新方法单独记录，不会把听过、看过直接算成掌握，也不代替原有每日任务。</p></section><section class="panel glass"><h2>挑一篇，慢慢听懂</h2><div class="method-lesson-list">${LIBRARY.filter(x=>x.kind==='听力').map(x=>`<div><strong>${esc(x.title)}</strong><p class="caption">${M.LISTENING_TIMING[x.id].sentences.length} 句 · 原创合成音频 · 非雅思真题</p>${button('逐句练习','method-listen',`data-lesson="${x.id}"`,'btn secondary')}</div>`).join('')}</div></section><section class="panel glass"><h2>今天，多照顾一下这些错题</h2><p>${due.length} 条已到错因复习日期，${untagged.length} 条还没选错因。</p>${due.slice(0,5).map(m=>`<div class="method-review"><span class="pill">${esc(M.REASONS[s.methods.reasons[m.id].reason])}</span><p>${esc(m.prompt)}</p>${button('先重练原题','method-retry',`data-id="${esc(m.id)}"`,'btn secondary')}${button('换个练法检验','method-target',`data-id="${esc(m.id)}"`,'btn ghost')}</div>`).join('')||'<p class="caption">到期内容会留在这里，直到原题被重新巩固。练了别的题，不会替你消除原来的错误。</p>'}${button('给错题选错因','method-reasons','','btn secondary')}</section><section class="panel glass"><h2>短句输出练习</h2><div class="topic-tags">${M.OUTPUTS.map(q=>button(`${q.id.slice(1)} · ${esc(q.topic)}`,'method-output',`data-output="${q.id}"`,'btn ghost')).join('')}</div><p class="caption">12 组原创基础句。开放译法由你对照自查，不冒充 AI 或雅思评分。</p></section>`;
 }
 function listenView(){
  const s=getState(),r=s.methods.listening[lesson],data=M.LISTENING_TIMING[lesson],item=LIBRARY.find(x=>x.id===lesson),stage=r.stage;
  if(stage===3)return head('ONE SMALL CHAPTER, COMPLETED','这一小段，已经认真练过了',item.title)+`<section class="panel glass"><p>你的大意：${esc(r.gist)}</p><p>跟读记录：${r.shadowed.length} / ${data.sentences.length} 句（自行确认）。${r.unclear.length?`仍有 ${r.unclear.length} 句标记为没听懂，可以继续复习。`:'没有待复习的句子标记。'}</p><p class="caption">完成练习不等于已掌握，也不代表发音评分。</p>${button('再走一遍三步练习','method-listen-restart')}${button('返回今日路线','method-home','','btn secondary')}</section>`;
  return head('LISTEN, NOTICE, SAY IT','一小段，也能听得更清楚',item.title)+`<div class="method-stage" aria-label="精听步骤">${['先听大意','对照文本','隐藏文本跟读'].map((x,i)=>`<span class="${stage===i?'active':''}">${i+1}. ${x}</span>`).join('')}</div><section class="panel glass listening-player method-listening"><div class="speech-options">${voiceSelect(true)}</div><audio data-listening="${lesson}" data-method-audio controls preload="metadata" src="${listeningPath(lesson)}" aria-label="${esc(item.title)} 精听音频"></audio><label>播放速度 <select data-listening-rate><option value="0.75">0.75 倍</option><option value="1" selected>1 倍</option></select></label><p class="caption" role="status">原创合成练习 · 非雅思真题。${stage===0?'先听整段，不急着看文本。':'点“听这一句”，播放会在句末停下；也可以选择循环。'}</p>${stage===0?`<form id="method-gist"><div class="field"><label for="method-gist-text">你听出了什么大意？中文或英文都可以</label><textarea id="method-gist-text" name="gist" maxlength="500" required>${esc(r.gist)}</textarea></div><button class="btn" type="submit">保存大意，开始对照文本</button></form>`:`<div class="method-sentence"><div class="panel-head"><strong>第 ${index+1} / ${data.sentences.length} 句</strong><label class="check-label"><input data-method-loop type="checkbox" ${loop?'checked':''}>循环这一句</label></div>${stage===1?`<p class="training-sentence" lang="en">${esc(data.sentences[index])}</p>`:`<p>先听一句，再用自己的声音跟读。</p><details><summary>需要时看一眼文本</summary><p lang="en" class="training-sentence">${esc(data.sentences[index])}</p></details>`}<div class="actions">${button('听这一句','method-play')}${button('上一句','method-prev',index===0?'disabled':'','btn secondary')}${button('下一句','method-next',index===data.sentences.length-1?'disabled':'','btn secondary')}</div><div class="actions">${button(r.unclear.includes(index)?'这句已听懂，移出待复习':'这句没听懂，稍后再练','method-unclear','','btn ghost')}${stage===2?button(r.shadowed.includes(index)?'✓ 这句跟读过了':'这句跟读过了','method-shadow','data-method-shadow '+(heardIndex===index?'':'disabled'),'btn secondary'):''}</div><p class="caption" data-method-play-status role="status">${r.unclear.includes(index)?'已留在错题本，可给它选一个错因。':'不用一次听懂，反复听同一句也可以。'}${stage===2?` 已跟读 ${r.shadowed.length}/${data.sentences.length} 句；由你确认，不做发音评分。`:''}</p>${stage===1?button('我已对照文本，开始隐藏跟读','method-listen-advance','','btn secondary'):button('完成这篇三步练习','method-listen-advance',r.shadowed.length===data.sentences.length?'':'disabled')}${button('给错题选错因','method-reasons','','btn ghost')}</div>`}</section>${button('返回今日路线','method-home','','text-btn')}`;
 }
 function outputView(){
  const q=M.OUTPUTS.find(q=>q.id===outputId),r=getState().methods.output[outputId];
  if(r.stage===3)return head('A SENTENCE OF YOUR OWN','这句话，已经练过一遍了',r.selfChecked?'你已对照自查；这不是自动判分。':'本次符合本题参考句型。')+`<section class="panel glass"><p class="training-sentence" lang="en">${esc(r.answer)}</p><p>${esc(q.chinese)}</p><p>${esc(q.tip)}</p>${button('练下一句','method-output-next')}${button('再从例句开始','method-output-restart','','btn secondary')}${button('返回今日路线','method-home','','btn ghost')}</section>`;
  const intro=r.stage===0,fill=r.stage===1;
  return head('LESS HELP, MORE RECALL','把提示，慢慢拿开',`${q.topic} · 原创基础练习`)+`<div class="method-stage"><span class="${intro?'active':''}">1. 看例句</span><span class="${fill?'active':''}">2. 补缺词</span><span class="${r.stage===2?'active':''}">3. 中译英</span></div><section class="panel glass method-output"><p>${esc(q.chinese)}</p>${intro?`<p class="training-sentence" lang="en">${esc(q.english)}</p><p>${esc(q.tip)}</p><div class="actions">${button('听例句','method-output-speak','','btn secondary')}${button('我看懂了，隐藏部分提示','method-output-hide')}</div>`:`${fill?`<p class="training-sentence" lang="en">${esc(q.mask)}</p><p class="caption">按刚才的例句补全缺失部分，保持本题句型。</p>`:`<p class="caption">按「${esc(q.topic)}」写完整英文。不必追求复杂。</p><button type="button" class="text-btn" data-action="method-output-hint">${showHint?'收起词语提示':'给我一点词语提示'}</button>${showHint?`<p class="notice" lang="en">${esc(q.hint)}</p>`:''}`}<form id="method-output-form"><div class="field"><label for="method-output-answer">${fill?'填入缺少的部分':'试着写一句英文'}</label><input id="method-output-answer" name="answer" lang="en" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="300" required value="${esc(draft)}"></div><button class="btn" type="submit">${fill?'核对这一空':'对照参考句型'}</button></form>${feedback?`<div class="feedback"><strong>${fill?'再对照这部分，试一次。':'和本题参考句型不同，先自己检查一下。'}</strong><p lang="en">${esc(fill?q.gap:q.english)}</p><p>${esc(q.tip)}</p>${!fill?`<p class="caption">其他表达也可能合理，这里没有 AI 或老师自动判分。</p><div class="actions">${button('我确实写错了，放入复习','method-output-wrong','','btn secondary')}${button('我已自行核对，记一次练习','method-output-self','','btn ghost')}</div>`:''}</div>`:''}`}</section>${button('返回今日路线','method-home','','text-btn')}`;
 }
 function reasonsView(){const s=getState(),all=s.mistakes.filter(m=>!m.resolved),selected=all.find(m=>m.id===reasonId);return head('NOTICE THE REASON','照顾错因，慢慢练稳','由你选择原因。先安排明天再练，已到期的内容会优先出现在今日路线。')+`<section class="panel glass">${selected?`<h2>${esc(selected.prompt)}</h2><p>上次作答：${esc(selected.userAnswer||'未记录')}</p><form id="method-reason-form"><input type="hidden" name="mistakeId" value="${esc(selected.id)}"><div class="field"><label for="method-reason">这次主要卡在哪里？</label><select id="method-reason" name="reason" required><option value="" disabled ${s.methods?.reasons[selected.id]?'':'selected'}>选一个最接近的原因</option>${Object.entries(M.REASONS).map(([id,label])=>`<option value="${id}" ${s.methods?.reasons[selected.id]?.reason===id?'selected':''}>${label}</option>`).join('')}</select></div><button class="btn" type="submit">保存错因，安排明天再练</button></form>${button('重练原题','method-retry',`data-id="${esc(selected.id)}"`,'btn secondary')}`:'<p>从下面选一道需要多照顾一下的题。</p>'}${all.slice(0,30).map(m=>`<div class="method-review"><span class="pill">${esc(m.category)}</span><p>${esc(m.prompt)}</p><p class="caption">${s.methods?.reasons[m.id]?`${esc(M.REASONS[s.methods.reasons[m.id].reason])} · ${s.methods.reasons[m.id].next} 再练`:'还没有选择错因'}</p>${button('选择 / 修改错因','method-reason',`data-id="${esc(m.id)}"`,'btn ghost')}</div>`).join('')||'<p>当前没有待巩固的错题。</p>'}</section>${button('返回今日路线','method-home','','text-btn')}`;}
 function openListen(id='l01',at=0,review=false){leave();stopAudio();commit(s=>{const r=M.listening(s,id);if(review)r.stage=2;});lesson=id;index=at;mode='listen';feedback=null;sessionDate=C.today();go('methods');}
 function openOutput(id){leave();stopAudio();id=id||M.suggestedOutput(getState())[0].id;commit(s=>M.output(s,id));outputId=id;mode='output';feedback=null;draft=getState().methods.output[id].stage===2?getState().methods.output[id].answer:'';showHint=false;sessionDate=C.today();go('methods');}
 function openReason(id=null){leave();stopAudio();reasonId=id;mode='reasons';sessionDate=C.today();go('methods');}
 function view(){if(sessionDate!==C.today()){mode='home';sessionDate=C.today();}return mode==='listen'?listenView():mode==='output'?outputView():mode==='reasons'?reasonsView():home();}
 function segment(){const voice=getVoice()==='device'?'M2':getVoice();return M.LISTENING_TIMING[lesson].voices[voice][index];}
 function watch(audio){stopLoop();const r=getState().methods?.listening[lesson];if(!r||r.stage===0||r.stage===3)return;const [start,end]=segment();if(audio.currentTime<start||audio.currentTime>=end)audio.currentTime=start;
  const tick=()=>{if(!audio.isConnected||audio.paused)return;if(audio.currentTime>=end-.015){if(loop){audio.currentTime=start;}else{audio.pause();return;}}raf=requestAnimationFrame(tick);};raf=requestAnimationFrame(tick);
 }
 document.addEventListener('playing',e=>{const a=e.target;if(!a.matches?.('audio[data-method-audio]')||mode!=='listen')return;commit(s=>M.heard(s,lesson));heardIndex=index;const b=document.querySelector('[data-method-shadow]');if(b)b.disabled=false;watch(a);},true);
 document.addEventListener('visibilitychange',()=>{if(document.hidden){stopLoop();document.querySelector('audio[data-method-audio]')?.pause();}});
 function act(action,el){if(!action.startsWith('method-'))return false;if(sessionDate!==C.today()&&!['method-home','method-listen','method-output','method-reasons','method-reason'].includes(action)){leave();mode='home';sessionDate=C.today();render();toast('日期已变化，今天可以从这里继续。');return true;}
  if(action==='method-home'){leave();stopAudio();mode='home';go('methods');}
  if(action==='method-words'){leave();openWords();}
  if(action==='method-dictation'){leave();openDictation();}
  if(action==='method-listen')openListen(el.dataset.lesson);
  if(action==='method-output')openOutput(el.dataset.output);
  if(action==='method-reasons')openReason();
  if(action==='method-reason')openReason(el.dataset.id);
  if(action==='method-retry'){leave();retryMistake(el.dataset.id);}
  if(action==='method-target'){const s=getState(),m=s.mistakes.find(m=>m.id===el.dataset.id),reason=s.methods?.reasons[m?.id]?.reason;if(!m)return true;const ear=earRef(m.refId),wid=m.refId?.startsWith('listen:')?m.refId.slice(7):m.refId;if(ear){openListen(ear.lesson,ear.index,true);}else if(['word','sound','spelling'].includes(reason)&&/^w\d+$/.test(wid||'')){leave();openDictation(wid);}else if(!['tense','negative'].includes(reason)){leave();retryMistake(m.id);toast('回到原题，对照文本找出卡住的位置。');}else{const old=outputRef(m.refId),topic=reason==='negative'?'否定':reason==='tense'?'过去':null;const q=M.OUTPUTS.find(q=>q.id!==old?.id&&(!topic||q.topic.includes(topic)));openOutput(q.id);toast('这是针对同类问题的新句子；原错题仍保留。');}}
  if(action==='method-play'){const a=document.querySelector('audio[data-method-audio]');stopAudio();const [start]=segment();a.currentTime=start;a.play().catch(()=>toast('请再点一次播放，并检查媒体音量。'));}
  if(action==='method-prev'||action==='method-next'){leave();stopAudio();index=Math.max(0,Math.min(M.LISTENING_TIMING[lesson].sentences.length-1,index+(action==='method-next'?1:-1)));render();}
  if(action==='method-unclear'){const r=getState().methods.listening[lesson];commit(s=>M.unclear(s,lesson,index,!r.unclear.includes(index)));leave();stopAudio();render();}
  if(action==='method-shadow'){if(heardIndex!==index)throw Error('请先播放这一句，再自行确认跟读。');commit(s=>M.shadow(s,lesson,index));leave();stopAudio();render();}
  if(action==='method-listen-advance'){leave();stopAudio();commit(s=>M.advanceListening(s,lesson));index=0;render();}
  if(action==='method-listen-restart'){leave();commit(s=>{s.methods.listening[lesson]={stage:0,gist:'',played:false,shadowed:[],unclear:[...s.methods.listening[lesson].unclear],last:C.today()};});index=0;render();}
  if(action==='method-output-speak'){stopAudio();speech.speak(M.OUTPUTS.find(q=>q.id===outputId).english);}
  if(action==='method-output-hide'){leave();commit(s=>{M.output(s,outputId).stage=1;});feedback=null;render();}
  if(action==='method-output-hint'){showHint=!showHint;render();}
  if(action==='method-output-wrong'){const m=commit(s=>M.confirmOutput(s,outputId,true));openReason(m.id);}
  if(action==='method-output-self'){commit(s=>M.confirmOutput(s,outputId,false));feedback=null;render();}
  if(action==='method-output-restart'){commit(s=>{const r=M.output(s,outputId);r.stage=0;r.selfChecked=false;});feedback=null;draft='';render();}
  if(action==='method-output-next'){const i=M.OUTPUTS.findIndex(q=>q.id===outputId);openOutput(M.OUTPUTS[(i+1)%M.OUTPUTS.length].id);}
  return true;
 }
 function submit(form,values){if(!['method-gist','method-output-form','method-reason-form'].includes(form.id))return false;try{if(sessionDate!==C.today())throw Error('日期已变化，请返回今日路线再开始。');if(form.id==='method-gist'){leave();stopAudio();commit(s=>M.advanceListening(s,lesson,values.gist));index=0;render();}if(form.id==='method-output-form'){const fill=getState().methods.output[outputId].stage===1,correct=commit(s=>fill?M.fillOutput(s,outputId,values.answer):M.checkOutput(s,outputId,values.answer));draft=correct?'':values.answer;feedback=correct?null:{answer:values.answer};leave();stopAudio();render();}if(form.id==='method-reason-form'){commit(s=>M.setReason(s,values.mistakeId,values.reason));toast('已安排明天再练；原题不会自动移出错题本。');render();}}catch(e){toast(e.message);}return true;}
 function input(e){if(e.target.id==='method-output-answer')draft=e.target.value;if(e.target.matches('[data-method-loop]'))loop=e.target.checked;if(e.target.matches('[data-voice-choice]')){stopLoop();heardIndex=null;const b=document.querySelector('[data-method-shadow]');if(b)b.disabled=true;}}
 return {view,act,submit,input,leave,openListen,openOutput,openReason,reset(){leave();mode='home';feedback=null;reasonId=null;},intro:()=>`<section class="panel glass method-entry"><h2>今天，照着这条路线学</h2><p>约 25 分钟：复习 → 听写 → 逐句精听 → 中译英小阶梯。</p><a href="#methods" class="btn secondary">打开今日方法路线</a></section>`};
}
